            <label style="display:flex;align-items:center;gap:8px;padding:4px 0;color:#718096;">
                <input type="checkbox" checked disabled> <?= htmlspecialchars($t['necessary']) ?>
            </label>
            <label style="display:flex;align-items:center;gap:8px;padding:4px 0;cursor:pointer;">
                <input type="checkbox" id="ik-consent-analytics"> <?= htmlspecialchars($t['analytics']) ?>
            </label>
            <label style="display:flex;align-items:center;gap:8px;padding:4px 0;cursor:pointer;">
                <input type="checkbox" id="ik-consent-marketing"> <?= htmlspecialchars($t['marketing']) ?>
            </label>
        </div>
        <div style="display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-end;">
            <button type="button" id="ik-consent-customize" style="padding:8px 14px;border:1px solid #cbd5e0;background:#fff;color:#4a5568;border-radius:6px;font-size:.86rem;cursor:pointer;">
                <?= htmlspecialchars($t['customize']) ?>
            </button>
            <button type="button" id="ik-consent-reject" style="padding:8px 14px;border:1px solid #cbd5e0;background:#fff;color:#4a5568;border-radius:6px;font-size:.86rem;cursor:pointer;">
                <?= htmlspecialchars($t['reject_all']) ?>
            </button>
            <button type="button" id="ik-consent-save" style="display:none;padding:8px 14px;border:none;background:#2563eb;color:#fff;border-radius:6px;font-size:.86rem;cursor:pointer;font-weight:600;">
                <?= htmlspecialchars($t['save']) ?>
            </button>
            <button type="button" id="ik-consent-accept" style="padding:8px 16px;border:none;background:#2563eb;color:#fff;border-radius:6px;font-size:.86rem;cursor:pointer;font-weight:600;">
                <?= htmlspecialchars($t['accept_all']) ?>
            </button>
        </div>
    </div>
    <script>
    (function () {
        var box = document.getElementById('ik-consent');
        var opts = document.getElementById('ik-consent-options');
        var btnCustomize = document.getElementById('ik-consent-customize');
        var btnReject    = document.getElementById('ik-consent-reject');
        var btnAccept    = document.getElementById('ik-consent-accept');
        var btnSave      = document.getElementById('ik-consent-save');
        var cbAnalytics  = document.getElementById('ik-consent-analytics');
        var cbMarketing  = document.getElementById('ik-consent-marketing');

        function setConsent(analytics, marketing) {
            var c = { necessary: true, analytics: !!analytics, marketing: !!marketing, ts: Math.floor(Date.now() / 1000) };
            // 1 年有效期；HTTPS 下加 Secure，避免 cookie 通过明文 HTTP 泄漏
            var secureFlag = (location.protocol === 'https:') ? ';Secure' : '';
            document.cookie = 'ik_consent=' + encodeURIComponent(JSON.stringify(c)) + ';path=/;max-age=' + (365 * 86400) + ';SameSite=Lax' + secureFlag;
            window.IK_consent = c;
            box.style.display = 'none';
            // 触发自定义事件，其他脚本可监听后挂载（如 GA）
            try { window.dispatchEvent(new CustomEvent('ik:consent', { detail: c })); } catch (e) {}
        }

        btnCustomize.addEventListener('click', function () {
            opts.style.display = 'block';
            btnCustomize.style.display = 'none';
            btnSave.style.display = 'inline-block';
        });
        btnAccept.addEventListener('click', function () { setConsent(true, true); });
        btnReject.addEventListener('click', function () { setConsent(false, false); });
        btnSave.addEventListener('click', function () { setConsent(cbAnalytics.checked, cbMarketing.checked); });
    })();
    </script>
    <?php
})

add_action('ik_head', function () {
    $raw = $_COOKIE['ik_consent'] ?? '';
    $consent = ['necessary' => true, 'analytics' => false, 'marketing' => false, 'ts' => 0];
    if ($raw) {
        $decoded = json_decode($raw, true);
        if (is_array($decoded)) {
            $consent['analytics'] = !empty($decoded['analytics']);
            $consent['marketing'] = !empty($decoded['marketing']);
            $consent['ts']        = (int)($decoded['ts'] ?? 0);
        }
    }
    // JSON_HEX_TAG 防御性转义：未来若 $consent 含字符串字段，避免 </script> 破出脚本。
    echo '<script>window.IK_consent = ' . json_encode($consent, JSON_UNESCAPED_SLASHES | JSON_HEX_TAG) . ';</script>' . "\n";
})

add_action('ik_admin_footer_scripts', function () {
    $order = config('admin_menu_order', '');
    if (empty($order)) return;

    $orderJson = json_encode($order, JSON_HEX_TAG | JSON_HEX_AMP);
    echo '<script>';
    echo '(function(){';
    echo 'try{';
    echo 'var cfg=JSON.parse(' . $orderJson . ');';
    echo 'if(!cfg||!cfg.groups)return;';
    echo 'var sidebar=document.querySelector("nav[x-data]");';
    echo 'if(!sidebar)return;';
    // 收集所有分组：header(.sidebar-group) + content(下一个兄弟div)
    echo 'var groupMap={};';
    echo 'sidebar.querySelectorAll(".sidebar-group").forEach(function(hdr){';
    echo '  var attr=hdr.getAttribute("@click")||"";';
    echo '  var m=attr.match(/toggle\\([\'"]([^\'"]+)[\'"]/);';
    echo '  if(m){';
    echo '    groupMap[m[1]]={header:hdr,content:hdr.nextElementSibling};';
    echo '  }';
    echo '});';
    // 隐藏的分组和菜单项
    echo 'var hidden=cfg.hidden||[];';
    echo 'var hiddenItems=cfg.hiddenItems||[];';
    // 创建容器，把排序后的元素放进去（避免空白残留）
    echo 'var dashLink=sidebar.querySelector("a.sidebar-link");';
    echo 'var frag=document.createDocumentFragment();';
    echo 'cfg.groups.forEach(function(g){';
    echo '  if(!groupMap[g])return;';
    echo '  if(hidden.indexOf(g)>=0){';
    echo '    groupMap[g].header.style.display="none";';
    echo '    groupMap[g].content.style.display="none";';
    echo '  }';
    echo '  frag.appendChild(groupMap[g].header);';
    echo '  frag.appendChild(groupMap[g].content);';
    echo '});';
    // 清空侧边栏，保留控制台链接，然后插入排序后的内容
    echo 'sidebar.innerHTML="";';
    echo 'if(dashLink)sidebar.appendChild(dashLink);';
    echo 'sidebar.appendChild(frag);';
    // 重排分组内的菜单项 + 隐藏
    echo 'if(cfg.items){';
    echo '  Object.keys(cfg.items).forEach(function(gn){';
    echo '    if(!groupMap[gn])return;';
    echo '    var ct=groupMap[gn].content;';
    echo '    var linkMap={};';
    echo '    ct.querySelectorAll("a.sidebar-link").forEach(function(a){';
    echo '      var m=(a.getAttribute("href")||"").match(/\\/admin\\/([^\\.]+)\\.php/);';
    echo '      if(m)linkMap[m[1]]=a;';
    echo '    });';
    echo '    cfg.items[gn].forEach(function(key){';
    echo '      if(!linkMap[key])return;';
    echo '      if(hiddenItems.indexOf(key)>=0){';
    echo '        linkMap[key].style.display="none";';
    echo '      }else{';
    echo '        ct.appendChild(linkMap[key]);';
    echo '      }';
    echo '    });';
    echo '  });';
    echo '}';
    echo '}catch(e){console.error("menu-sort:",e)}';
    echo '})();';
    echo '</script>';
})

add_action('ik_admin_footer_scripts', function () {
    // 在插件管理页面下方添加入口提示
    $currentPage = basename($_SERVER['SCRIPT_NAME'] ?? '');
    if ($currentPage !== 'plugin.php') return;
    echo '<script>
    (function(){
        var list = document.getElementById("pluginList");
        if (!list) return;
        var card = document.getElementById("plugin-search-replace");
        if (!card) return;
        var info = card.querySelector(".text-xs.text-gray-400");
        if (info) {
            var link = document.createElement("a");
            link.href = "/admin/plugin_page.php?plugin=search-replace";
            link.className = "text-primary hover:underline ml-4";
            link.textContent = "进入管理页面";
            info.appendChild(link);
        }
    })();
    </script>';
})

add_action('ik_head', function () {
    $provider = (string) config('stats_provider', '');
    if ($provider === '') {
        return;
    }

    if ($provider === 'custom') {
        // 自定义代码原样输出（与系统「Body代码」同等信任级别，由站长自负）
        $code = (string) config('stats_custom_code', '');
        if (trim($code) !== '') {
            echo "\n<!-- stats: custom -->\n" . $code . "\n";
        }
        return;
    }

    // 预设服务商：ID 仅允许字母数字（含 - _），防止注入
    $id = preg_replace('/[^A-Za-z0-9\-_]/', '', (string) config('stats_id', ''));
    if ($id === '') {
        return;
    }

    $out = '';
    switch ($provider) {
        case 'baidu':
            $out = '<script>var _hmt=_hmt||[];(function(){var hm=document.createElement("script");'
                 . 'hm.src="https://hm.baidu.com/hm.js?' . $id . '";'
                 . 'var s=document.getElementsByTagName("script")[0];s.parentNode.insertBefore(hm,s);})();</script>';
            break;

        case '51la':
            $out = '<script charset="UTF-8" id="LA_COLLECT" src="//sdk.51.la/js-sdk-pro.min.js?id='
                 . $id . '&ck=' . $id . '"></script>';
            break;

        case 'cnzz':
            $out = '<script async src="https://s9.cnzz.com/z_stat.php?id=' . $id . '&web_id=' . $id . '"></script>';
            break;

        case 'ga4':
            $out = '<script async src="https://www.googletagmanager.com/gtag/js?id=' . $id . '"></script>'
                 . '<script>window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}'
                 . "gtag('js',new Date());gtag('config','" . $id . "');</script>";
            break;
    }

    if ($out !== '') {
        echo "\n<!-- stats: " . $provider . " -->\n" . $out . "\n";
    }
})
